import React, { useEffect, useRef, useState } from 'react';
import { Badge, Button, Form, Spinner } from 'react-bootstrap';
import { reportFilterFormContainer, staffSalaryBtn } from './formFieldData';
import Table from '../../../components/Table';
import { dateConversion, findArrObj, showConfirmationDialog, showMessage } from '../../../utils/AllFunction';
import { usePageTitle, useRedux } from '../../../hooks'
import { NotificationContainer } from 'react-notifications';
import {
    getBranchRequest, getClaimRequest, getDepartmentRequest, resetGetBranch, resetGetClaim, resetGetDepartment,
    createStaffRemainingLeaveRequest,
    getStaffRemainingLeaveRequest,
    getStaffRequest,
    resetCreateStaffRemainingLeave,
    resetGetStaff,
    resetGetStaffRemainingLeave,
    resetUpdateStaffRemainingLeave,
    updateStaffRemainingLeaveRequest,
} from '../../../redux/actions';
import moment from 'moment';
import * as XLSX from "xlsx";
import { useNavigate } from 'react-router-dom';
import _ from 'lodash';
import noProfile from '../../../assets/images/noprofile_images.jpg';
import { baseURL } from '../../../api/ApiConfig';

function Index() {

    usePageTitle({
        title: 'Report',
        breadCrumbItems: [
            {
                path: '/report/leave-remaining-report',
                label: 'Report',
            },
            {
                path: '/report/leave-remaining-report',
                label: 'Leave Remaining Report',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData[0].pagePermission, 'label', "Remaining Leave Report");
    const accessIds = (pageAccessData[0]?.access || '').split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData[0]?.branchId || 0; // for branch list can only show
    const roleIdforRole = localData[0].roleId; // for role Permission (1.superadmin,2.admin)

    const incentiveAmountRefs = useRef([]);
    const navigate = useNavigate();

    const {
        getBranchSuccess, getBranchList, getBranchFailure,
        getDepartmentSuccess, getDepartmentList, getDepartmentFailure,
        getStaffRemainingLeaveSuccess,
        getStaffRemainingLeaveList,
        getStaffRemainingLeaveFailure,
        errorMessage,
    } = appSelector((state) => ({

        getBranchSuccess: state.branchReducer.getBranchSuccess,
        getBranchList: state.branchReducer.getBranchList,
        getBranchFailure: state.branchReducer.getBranchFailure,

        getDepartmentSuccess: state.departmentReducer.getDepartmentSuccess,
        getDepartmentList: state.departmentReducer.getDepartmentList,
        getDepartmentFailure: state.departmentReducer.getDepartmentFailure,

        getStaffRemainingLeaveSuccess: state.staffLeaveReducer.getStaffRemainingLeaveSuccess,
        getStaffRemainingLeaveList: state.staffLeaveReducer.getStaffRemainingLeaveList,
        getStaffRemainingLeaveFailure: state.staffLeaveReducer.getStaffRemainingLeaveFailure,

        getClaimSuccess: state.claimReducer.getClaimSuccess,
        getClaimList: state.claimReducer.getClaimList,
        getClaimFailure: state.claimReducer.getClaimFailure,

        errorMessage: state.staffLeaveReducer.errorMessage,

        errorMessage: state.claimReducer.errorMessage,
    }));

    const columns = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,
        },
        {
            Header: "Staff",
            accessor: 'staffName',
            Cell: ({ row }) => (
                <div className="inbox-item-img" style={{ display: 'flex', alignItems: 'center' }}>
                    <img
                        src={row?.original?.staffProfile ? `${baseURL}${row?.original.staffProfile}` : noProfile}
                        alt="staffProfile"
                        className="rounded-circle"
                        crossOrigin="anonymous"
                        onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = noProfile;
                        }}
                        style={{ width: "40px", height: "40px", objectFit: "cover", marginRight: "10px" }}
                    />
                    <div>
                        <div style={{ fontSize: '15px', fontWeight: '600' }}>
                            {row?.original?.staffName}
                        </div>
                        <div style={{ fontSize: '12px', color: '#888' }}>
                            {row?.original?.staffCode}
                        </div>
                    </div>
                </div>
            )
        },
        {
            Header: 'Total Leave',
            accessor: 'totalTakenLeave',
        },
        {
            Header: 'Casual Leave',
            accessor: 'casualLeave',
        },
        {
            Header: 'Less of Pay',
            accessor: 'lessOfPayLeave',
        },
        {
            Header: 'Remaining Leave',
            accessor: 'remainingLeave',
            Cell: ({ value }) => {
                return <div style={{ "color": value >= 1 ? "green" : "red", fontWeight: "600" }}>
                    {value}
                </div>
            }
        }
    ];
    const onFromDate = (event, formName) => {
        setState({
            ...state,
            [formName]: event.target.value,
        })
        const filterDate = {
            year: event.target.value,
            branchId: state.branchId || '',
            staffId: state.staffId || '',
            departmentId: state.departmentId || '',
            yearOrMonth: state?.yearOrMonth || '',

        }
        dispatch(getStaffRemainingLeaveRequest(filterDate));
        setIsLoading(true)
    }
    const onYearOrMonthFilter = (options, formName) => {
        setState({
            ...state,
            [formName]: options[formName]
        })
        const filterDate = {
            [formName]: options[formName],
            branchId: state.branchId || '',
            staffId: state.staffId || '',
            departmentId: state.departmentId || '',
            year: state.year || '',
        }
        dispatch(getStaffRemainingLeaveRequest(filterDate));
        setIsLoading(true)
    }
    const [state, setState] = useState({
        // applyDate: moment().format('YYYY-MM-DD'),
        year: moment().format('YYYY-MM'),
        departmentId: 0,
        branchId: branchIdforRole,
        yearOrMonth: 2,
    });
    const [optionListState, setOptionListState] = useState({
        departmentList: [
            {
                "departmentId": 0,
                "departmentName": "All",
            },
        ],
        yearOrMonthList: [
            {
                "yearOrMonth": 2,
                "yearOrMonthName": "Month",
            },
            {
                "yearOrMonth": 4,
                "yearOrMonthName": "Year",
            },
        ],
        branchList: [{
            "branchId": 0,
            "branchName": "All",
        }],
    })
    const [parentList, setParentList] = useState([]);
    const [formContain, setFormContain] = useState(reportFilterFormContainer);
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        setIsLoading(true)
        dispatch(getBranchRequest());
        dispatch(getDepartmentRequest());
        const searchReq = {
            year: state?.year,
            branchId: branchIdforRole || '',
            departmentId: state.departmentId || '',
            yearOrMonth: state?.yearOrMonth || '',
        }
        dispatch(getStaffRemainingLeaveRequest(searchReq));
    }, []);

    useEffect(() => {
        if (roleIdforRole != 1) {
            let arr = reportFilterFormContainer;
            const updatedFormFields = _.filter(
                reportFilterFormContainer[0].formFields,
                (field) => field.name !== 'branchId'
            );
            arr[0].formFields = updatedFormFields;
            setFormContain(arr);
        }
    }, [reportFilterFormContainer, roleIdforRole]);


    useEffect(() => {
        if (getBranchSuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: [...optionListState.branchList, ...getBranchList],
            })
            dispatch(resetGetBranch())
        } else if (getBranchFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: []
            })
            dispatch(resetGetBranch())
        }
    }, [getBranchSuccess, getBranchFailure]);

    useEffect(() => {
        if (getDepartmentSuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                departmentList: [...optionListState.departmentList, ...getDepartmentList],
            })
            dispatch(resetGetDepartment())
        } else if (getDepartmentFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                departmentList: []
            })
            dispatch(resetGetDepartment())
        }
    }, [getDepartmentSuccess, getDepartmentFailure]);

    useEffect(() => {
        if (getStaffRemainingLeaveSuccess) {
            setIsLoading(false)
            setParentList(getStaffRemainingLeaveList)

            setIsLoading(false);
            dispatch(resetGetStaffRemainingLeave())
        } else if (getStaffRemainingLeaveFailure) {
            setIsLoading(false)
            setParentList([])
            dispatch(resetGetStaffRemainingLeave())
        }
    }, [getStaffRemainingLeaveSuccess, getStaffRemainingLeaveFailure]);

    const onDepartmentFilter = (option, formName, uniqueKey, displayKey) => {
        const filterDepartment = {
            departmentId: option[uniqueKey] || '',
            branchId: state?.branchId || '',
            year: state?.year,
            yearOrMonth: state?.yearOrMonth || '',
        }
        dispatch(getStaffRemainingLeaveRequest(filterDepartment));
        setIsLoading(true);
        setState({
            ...state,
            [formName]: option[uniqueKey],
        })
    }

    const onBranchFilter = (option, formName, uniqueKey, displayKey) => {
        const filterBranch = {
            branchId: option[uniqueKey] || '',
            departmentId: state?.departmentId || '',
            year: state?.year,
            yearOrMonth: state?.yearOrMonth || '',
        }
        dispatch(getStaffRemainingLeaveRequest(filterBranch));
        setIsLoading(true)
        setState({
            ...state,
            [formName]: option[uniqueKey],
        })
    }

    const onDownload = () => {
        const yearMonth = moment(state?.year).format("YYYY");
        const additionalDetails = `Leave Remaining Report for ${yearMonth}`;
        const reportGeneratedDate = `Report Generated On: ${moment().format("DD-MM-YYYY")}`;
        const data = parentList.map((item, i) => ({
            ["s.no"]: i + 1,
            staffName: item.staffName,
            totalTakenLeave: item.totalTakenLeave,
            casualLeave: item.casualLeave,
            lessOfPayLeave: item.lessOfPayLeave,
            remainingLeave: item.remainingLeave,
        }));
        const header = [
            [additionalDetails],
            [reportGeneratedDate],
            [],
            ["S.no", "Staff Name", "Total Leave", "Casual Leave", "Sick Leave", "Remaining Leave"]
        ];
        const rows = [
            ...header,
            ...data.map(item => [
                item["s.no"],
                item.staffName,
                item.totalTakenLeave,
                item.casualLeave,
                item.lessOfPayLeave,
                item.remainingLeave,
            ])
        ];
        const worksheet = XLSX.utils.aoa_to_sheet(rows);

        worksheet["!cols"] = [
            { wch: 10 },
            { wch: 20 },
            { wch: 20 },
            { wch: 15 },
            { wch: 15 },
            { wch: 12 },
            { wch: 12 },
            { wch: 10 },
        ];

        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, "Leave Remaining Report");

        XLSX.writeFile(workbook, `K3-Leave-Remaining-Report-${yearMonth}.xlsx`);
    };


    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? <div className='bg-light opacity-0.25'>
                <div className="d-flex justify-content-center m-5">
                    <Spinner className='mt-5 mb-5' animation="border" />
                </div>
            </div> :
                <Table
                    columns={columns}
                    Title={'Leave Report List'}
                    data={parentList || []}
                    pageSize={5}
                    toggle={false}
                    pagination={false}
                    filterTbl={true}
                    footerTbl={true}
                    filterFormContainer={formContain}
                    // onChangeCallBack={{ "onDateFilter": onDateFilter, "onDepartmentFilter": onDepartmentFilter, "onBranchFilter": onBranchFilter }}
                    onChangeCallBack={{ "onFromDate": onFromDate, "onDepartmentFilter": onDepartmentFilter, "onBranchFilter": onBranchFilter, "onYearOrMonthFilter": onYearOrMonthFilter }}

                    onClickCallBack={{ "onDownload": onDownload }}
                    optionListState={optionListState}
                    setState={setState}
                    state={state}
                    noOfColumns={1}
                />}
        </React.Fragment>
    );
}

export default Index;
